import React, { useState, useEffect, useMemo } from 'react';
import { DataGrid } from '@mui/x-data-grid';
import { searchTracks, getTrackDetails } from '../services/api';

const TrackSearch = ({ searchTerm }) => {
  const [filteredTracks, setFilteredTracks] = useState([]);
  const [trackDetails, setTrackDetails] = useState({});

  useEffect(() => {
    if (searchTerm) {
      searchTracks(searchTerm)
        .then(async (tracks) => {
          setFilteredTracks(tracks);
          const detailsPromises = tracks.map((track) =>
            getTrackDetails(track.id).then((details) => ({ [track.id]: details }))
          );
          const detailsArray = await Promise.all(detailsPromises);
          setTrackDetails(Object.assign({}, ...detailsArray));
        })
        .catch((error) => console.error('Error fetching tracks:', error));
    }
  }, [searchTerm]);

  const columns = useMemo(() => [
    { field: 'name', headerName: 'Track Name', minWidth: 150, flex: 1 },
    {
      field: 'artistName',
      headerName: 'Artist Name',
      minWidth: 150,
      flex: 1,
      valueGetter: (params) =>
        params.row?.artists && params.row.artists[0] ? params.row.artists[0].name : 'Unknown',
    },
    {
      field: 'albumName',
      headerName: 'Album Name',
      minWidth: 150,
      flex: 1,
      valueGetter: (params) => params.row?.album?.name || 'Unknown',
    },
    {
      field: 'releaseDate',
      headerName: 'Release Date',
      minWidth: 100,
      flex: 1,
      valueGetter: (params) => params.row?.album?.release_date?.split('-')[0] || 'Unknown',
    },
    {
      field: 'tempo',
      headerName: 'Tempo',
      minWidth: 80,
      flex: 1,
      valueGetter: (params) => trackDetails[params.row.id]?.tempo || '',
    },
    {
      field: 'key',
      headerName: 'Key',
      minWidth: 80,
      flex: 1,
      valueGetter: (params) => trackDetails[params.row.id]?.key || '',
    },
    {
      field: 'danceability',
      headerName: 'Danceability',
      minWidth: 80,
      flex: 1,
      valueGetter: (params) => trackDetails[params.row.id]?.danceability || '',
    },
    {
      field: 'energy',
      headerName: 'Energy',
      minWidth: 80,
      flex: 1,
      valueGetter: (params) => trackDetails[params.row.id]?.energy || '',
    },
    {
      field: 'valence',
      headerName: 'Valence',
      minWidth: 80,
      flex: 1,
      valueGetter: (params) => trackDetails[params.row.id]?.valence || '',
    },
    {
      field: 'acousticness',
      headerName: 'Acousticness',
      minWidth: 80,
      flex: 1,
      valueGetter: (params) => trackDetails[params.row.id]?.acousticness || '',
    },
    {
      field: 'instrumentalness',
      headerName: 'Instrumentalness',
      minWidth: 80,
      flex: 1,
      valueGetter: (params) => trackDetails[params.row.id]?.instrumentalness || '',
    },
    {
      field: 'liveness',
      headerName: 'Liveness',
      minWidth: 80,
      flex: 1,
      valueGetter: (params) => trackDetails[params.row.id]?.liveness || '',
    },
    {
      field: 'genre',
      headerName: 'Genre',
      minWidth: 100,
      flex: 1,
      valueGetter: (params) => trackDetails[params.row.id]?.genres?.join(', ') || '',
    },
    {
      field: 'preview',
      headerName: 'Preview',
      minWidth: 250,
      renderCell: (params) =>
        params.row.id ? (
          <iframe
            src={`https://open.spotify.com/embed/track/${params.row.id}`}
            width="240"
            height="80"
            allow="encrypted-media"
            frameBorder="0"
            style={{ border: 'none' }}
            title={`Spotify preview of ${params.row.id}`}
          ></iframe>
        ) : (
          'No Preview Available'
        ),
    },
  ], [trackDetails]);

  return (
    <div style={{ height: 600, width: '100%', marginTop: '20px' }}>
      <DataGrid
        rows={filteredTracks}
        columns={columns}
        getRowId={(row) => row.id}
        pageSize={10}
        autoHeight
      />
    </div>
  );
};

export default TrackSearch;
